
    window.dsUiStrings = {"auth_err_email_in_use": "\uc774\ubbf8 \ub4f1\ub85d\ub41c \uc774\uba54\uc77c\uc785\ub2c8\ub2e4. \ub85c\uadf8\uc778\ud574 \uc8fc\uc138\uc694.", "auth_err_invalid_credential": "\uc774\uba54\uc77c \uc8fc\uc18c \ub610\ub294 \ube44\ubc00\ubc88\ud638\uac00 \uc62c\ubc14\ub974\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.", "auth_err_invalid_email": "\uc720\ud6a8\ud55c \uc774\uba54\uc77c \uc8fc\uc18c\ub97c \uc785\ub825\ud574 \uc8fc\uc138\uc694.", "auth_err_user_not_found": "\ud574\ub2f9 \uc774\uba54\uc77c \uc8fc\uc18c\ub85c \uacc4\uc815\uc744 \uc0dd\uc131\ud55c \uc801\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.", "auth_err_weak_password": "\ube44\ubc00\ubc88\ud638\ub294 \ucd5c\uc18c 6\uc790 \uc774\uc0c1\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4.", "auth_err_wrong_password": "\ube44\ubc00\ubc88\ud638\uac00 \uc798\ubabb\ub418\uc5c8\uc2b5\ub2c8\ub2e4.", "connecting": "\uc5f0\uacb0 \uc911\u2026", "could_not_connect": "\uc5f0\uacb0\uc744 \uc2dc\uc791\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.", "explorer_fallback": "\ud0d0\ud5d8\uac00", "fill_all_fields": "\ubaa8\ub4e0 \ud56d\ubaa9\uc744 \ube60\uc9d0\uc5c6\uc774 \uc785\ub825\ud574 \uc8fc\uc2ed\uc2dc\uc624.", "firebase_not_ready": "Firebase\uac00 \uc544\uc9c1 \ucd08\uae30\ud654\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.", "join_wishlist": "\uc704\uc2dc\ub9ac\uc2a4\ud2b8\uc5d0 \ucd94\uac00", "tick_consent": "\uacc4\uc18d \uc9c4\ud589\ud558\ub824\uba74 \ub3d9\uc758\ud568\uc5d0 \uccb4\ud06c\ud574 \uc8fc\uc138\uc694."};
  